import { unicodeName } from '../names.js';
import type { Finding } from '../types.js';
import { codePointBefore, type CodePointInfo } from '../unicode-utils.js';
import { describeCodePoint, type PositionLookup } from './position.js';

// Unusual whitespace: visually indistinguishable (or nearly so) from a
// normal space/newline but tokenizes differently, which has been used to
// break out of string literals, defeat naive keyword filters, and confuse
// diff/review tooling. NBSP, the Zs space-separator block U+2000-200A and
// U+3000 (ideographic space), plus U+202F/U+205F (also General_Category=Zs,
// included alongside the brief's list for completeness) and the two
// non-ASCII line/paragraph separators U+2028/U+2029 and NEL U+0085.
const UNUSUAL_WHITESPACE = new Set([0x00a0, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x202f, 0x205f, 0x2028, 0x2029, 0x3000, 0x0085]);

const ESCAPE = 0x001b;

// BRAILLE PATTERN BLANK renders as an empty cell but is a symbol, not
// whitespace: trim() and word splitting leave it alone, which is why it turns
// up as a "blank" display name or a gap that isn't one. Between braille
// patterns it is the ordinary word space of braille text.
const BRAILLE_BLANK = 0x2800;

function isBraillePattern(cp: number | undefined): boolean {
  return cp !== undefined && cp > BRAILLE_BLANK && cp <= 0x28ff;
}

function isC0Control(cp: number): boolean {
  return cp <= 0x1f && cp !== 0x09 && cp !== 0x0a && cp !== 0x0d;
}

function isC1Control(cp: number): boolean {
  return cp >= 0x80 && cp <= 0x9f;
}

const NBSP = 0x00a0;
const NARROW_NBSP = 0x202f;
// French typography puts a (narrow) no-break space before ; : ! ? and » and after «.
const FRENCH_SPACED_AFTER = new Set([0x003b, 0x003a, 0x0021, 0x003f, 0x00bb]);
const GUILLEMET_OPEN = 0x00ab;

function isFrenchTypography(prev: number | undefined, cp: number, next: number | undefined): boolean {
  if (cp !== NBSP && cp !== NARROW_NBSP) return false;
  return (next !== undefined && FRENCH_SPACED_AFTER.has(next)) || prev === GUILLEMET_OPEN;
}

const IDEOGRAPHIC_SPACE = 0x3000;
// Chinese, Japanese and Korean text is set with the ideographic space: it is the space of the
// full-width grid (a paragraph indent, the gap between a title and its volume number), not a
// stand-in for U+0020. It is ordinary next to a character of those scripts or their
// punctuation, another ideographic space included.
const CJK_RANGES: ReadonlyArray<readonly [number, number]> = [
  [0x2e80, 0x303f], // CJK radicals, symbols and punctuation (the ideographic space is here)
  [0x3040, 0x30ff], // Hiragana, Katakana
  [0x3100, 0x318f], // Bopomofo, Hangul compatibility jamo
  [0x31a0, 0x31ff], // Bopomofo extended, CJK strokes, Katakana phonetic extensions
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xac00, 0xd7af], // Hangul syllables
  [0xf900, 0xfaff],
  [0xfe30, 0xfe4f], // CJK compatibility forms
  [0xff00, 0xffef], // halfwidth and fullwidth forms
  [0x20000, 0x2fa1f],
];

function isCjk(cp: number | undefined): boolean {
  return cp !== undefined && CJK_RANGES.some(([lo, hi]) => cp >= lo && cp <= hi);
}

// Everything this rule can flag: the C0 controls other than tab, LF and CR, the C1 controls
// (U+0085 among them), the unusual spaces above and the braille blank. All in the BMP.
// eslint-disable-next-line no-control-regex -- intentional: control characters are what this rule looks for.
const CANDIDATE_RE = /[\x00-\x08\x0b\x0c\x0e-\x1f\x80-\x9f\u00a0\u2000-\u200a\u2028\u2029\u202f\u205f\u2800\u3000]/g;

export function scanWhitespaceAndControl(text: string, positionAt: PositionLookup): Finding[] {
  const findings: Finding[] = [];
  CANDIDATE_RE.lastIndex = 0;
  for (let match = CANDIDATE_RE.exec(text); match !== null; match = CANDIDATE_RE.exec(text)) {
    const index = match.index;
    const codePoint = text.charCodeAt(index);
    const prev = (): number | undefined => codePointBefore(text, index);
    const next = (): number | undefined => text.codePointAt(index + 1);
    if (UNUSUAL_WHITESPACE.has(codePoint) && isFrenchTypography(prev(), codePoint, next())) continue;
    if (codePoint === BRAILLE_BLANK && (isBraillePattern(prev()) || isBraillePattern(next()))) continue;
    if (codePoint === IDEOGRAPHIC_SPACE && (isCjk(prev()) || isCjk(next()))) continue;

    const cp = describeCodePoint(text, index, positionAt);
    if (UNUSUAL_WHITESPACE.has(cp.codePoint)) {
      // Read in context across 83,000 public prompts and agent-instruction files, all but a handful of
      // these no-break spaces and line separators had been left by copying from a web page or a chat
      // window (studies/prompt-census).
      const usuallyPasted = cp.codePoint === NBSP || cp.codePoint === 0x2028 || cp.codePoint === 0x2029 ? ' Usually left by pasting from a web page or chat window.' : '';
      findings.push(finding(cp, 'unusual-whitespace', 'warning', `${unicodeName(cp.codePoint)} looks like a normal space or line break but is a distinct code point -- it can split tokens, defeat string/keyword matching, or hide in a diff.${usuallyPasted}`, 'Replace with a regular space (U+0020) or ASCII newline.'));
    } else if (cp.codePoint === BRAILLE_BLANK) {
      findings.push(finding(cp, 'unusual-whitespace', 'warning', 'BRAILLE PATTERN BLANK (U+2800) renders as an empty space but is not whitespace: trim() and word splitting leave it in, so it can pass for a blank name or a gap between words.', 'Replace with a regular space (U+0020); it belongs only between braille patterns.'));
    } else if (isC0Control(cp.codePoint) || isC1Control(cp.codePoint)) {
      const isEscape = cp.codePoint === ESCAPE;
      findings.push(
        finding(
          cp,
          'control-character',
          isEscape ? 'error' : 'warning',
          isEscape
            ? 'ESCAPE (U+001B) begins a terminal control sequence -- printed to a terminal, this can rewrite the prompt, hide text, or (on vulnerable terminals) inject keystrokes.'
            : `${unicodeName(cp.codePoint)} is a non-printing control character with no place in normal text.`,
          'Remove this character.',
        ),
      );
    }
  }
  return findings;
}

function finding(cp: CodePointInfo, rule: Finding['rule'], severity: Finding['severity'], message: string, suggestion: string): Finding {
  return {
    rule,
    severity,
    start: { line: cp.line, column: cp.column, offset: cp.index },
    end: { line: cp.line, column: cp.column + cp.width, offset: cp.index + cp.width },
    codePoints: [cp.codePoint],
    names: [unicodeName(cp.codePoint)],
    message,
    suggestion,
    fixable: true,
  };
}
